// Generated by scripts/split.py from cockpit/: edit there and run it again
import { expect, test } from 'claude-code/testing'
import type { Register } from 'claude-code'

// An add-on as core meets one: it calls $.cockpit, here on a tool call the test makes
const addon: Register = on => {
  on('tool.call', { tool: 'Probe' as never }, async ($, e) => {
    const i = e as unknown as { call: 'set' | 'act' | 'tab'; arg: never }
    const r = i.call === 'set' ? await $.cockpit.set(i.arg) : i.call === 'tab' ? await $.cockpit.tab(i.arg) : await $.cockpit.act(i.arg).catch((x: unknown) => `refused: ${String(x)}`)
    return { result: JSON.stringify(r ?? null) }
  })
}
const PANE = { plugin: 'cockpit-core', component: 'Pane', requestId: 'cockpit', props: { title: 'Cockpit', isFocused: true, bodyColumns: 72, placement: 'dock', scroll: { offset: 0, bodyRows: 60 }, view: {} } }

test('core draws the header alone until an add-on says it is here, then its tab; and answers set and act', { plugins: [{ name: 'probe', register: addon }] }, async ($, on) => {
  on('clock.now', async () => ({ value: 1_000_000 }))
  on('ui.toast', async () => ({ value: undefined }))
  on('ui.open', async () => ({ value: { isPlaced: true } }))
  on('store.set', async () => ({ value: undefined }))
  on('process.run', async () => ({ value: { exitCode: 0, stdout: '', stderr: '' } }) as never)
  on('ui.render', async (_, e) => {
    const { Text } = _.ui.resolve(e)
    return <Text>BELOW</Text>
  })
  const probe = (call: string, arg: unknown) => $.tool.call({ tool: 'Probe', call, arg } as never)
  const ui = await $.ui.mount({ ...PANE, surface: 'desktop' } as never)
  expect(JSON.stringify(await ui.drawn())).toContain('No tabs yet')
  await probe('tab', { id: 'git' })
  let drawn = JSON.stringify(await ui.drawn())
  expect(drawn).not.toContain('No tabs yet')
  expect(drawn).toContain('"label":"Git"')
  expect(drawn).not.toContain('"label":"Overview"')
  await probe('set', { patch: { mode: 'ask' } })
  expect(JSON.stringify(await ui.drawn())).toContain('Ask · advice')
  // An action is run by name; a name that is none of them is refused
  await probe('act', { name: 'stopAutopilot', args: [] })
  expect(JSON.stringify(await probe('act', { name: 'rm -rf', args: [] }))).toContain('refused')
  await ui.unmount()
})
